package com.thorium.preview.game;

import android.opengl.GLES20;
import android.opengl.GLES30;
import android.util.Log;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * GPU dense inverse search optical flow (Kroeger et al., ECCV 2016; our own
 * implementation from the paper). Shaders come from
 * {@link DenseInverseSearchShaders}, generated by
 * tools/learned_framegen/dis_gles.py; tools/learned_framegen/dis_eval.py runs
 * the same passes on a desktop GPU over captured hold-out triplets.
 *
 * Per real frame: luma of the history image box-filtered to the analysis size
 * (native up to 640 wide, a half up to 1280, else a quarter) and a 2x2-mean
 * pyramid, cached per frame. Per pair, both directions, coarse to fine down
 * to the full analysis resolution: 8x8 patches on a 3-px grid align by
 * inverse-compositional Gauss-Newton from the coarser flow; densification
 * gives each pixel the error-weighted mean of the covering patches. The output
 * pass samples the full-resolution history where the content comes from
 * (fixed point along each flow) and blends by the phase.
 *
 * All methods run on the GL thread of the owning generator.
 */
final class DenseInverseSearchFlow {
    private static final String TAG = "EmuFusionDisFlow";
    static final int PATCH = 8;
    static final int STRIDE = 3;

    private int historyWidth, historyHeight, divisor, finest, levels;
    // Finest level the last estimate reached.
    private int used;
    private int[][] sizes = new int[0][];
    private int[][] grids = new int[0][];
    private int gray, down, grad, patchSearch, densify, generate, toRaw;
    // QA synthesis 24: per-phase symmetric refinement of the DIS motion.
    private int phaseSearch, phaseDensify, generatePhase;
    private int phasePatches, phaseFlow, phaseLevel = -1;
    // Synthesis 22: DIS motion in the solver's raw format at its analysis grid,
    // then validated and filled by the generator's own passes ([0] current->
    // previous, [1] previous->current, like the solver's directions).
    final int[] motionRaw = new int[2], motionValidated = new int[2], motionFill = new int[2];
    private int motionWidth, motionHeight;
    private final Map<Integer, Map<String, Integer>> uniforms = new HashMap<>();
    private int[][] pyramid = new int[2][];       // [slot][level] R8 luma
    private int[][] gradients = new int[2][];     // [slot][level] RGBA16F (I, Ix, Iy)
    private int[][] patches = new int[2][];       // [direction][level] RGBA16F
    private int[][] flows = new int[2][];         // [direction][level] RGBA16F
    private int zeroField;
    private int framebuffer;
    private final Set<Integer> verifiedTargets = new HashSet<>();
    private final long[] slotKey = new long[2];
    private final List<Integer> owned = new ArrayList<>();
    private boolean ready, failed;
    private final int[] savedFramebuffer = new int[1];
    private final int[] savedViewport = new int[4];
    long encodes, estimates;

    boolean ensure(int width, int height) {
        if (failed) return false;
        if (ready && width == historyWidth && height == historyHeight) return true;
        try {
            if (generate == 0) compile();
            releaseTextures();
            historyWidth = width;
            historyHeight = height;
            divisor = width > 1280 ? 4 : width > 640 ? 2 : 1;
            int w = Math.max(1, width / divisor), h = Math.max(1, height / divisor);
            finest = 0;
            List<int[]> list = new ArrayList<>();
            list.add(new int[] {w, h});
            while (Math.min((list.get(list.size() - 1)[0] + 1) / 2,
                    (list.get(list.size() - 1)[1] + 1) / 2) >= 2 * PATCH) {
                int[] last = list.get(list.size() - 1);
                list.add(new int[] {(last[0] + 1) / 2, (last[1] + 1) / 2});
            }
            levels = list.size();
            if (finest >= levels) finest = levels - 1;
            sizes = list.toArray(new int[0][]);
            grids = new int[levels][];
            for (int k = 0; k < levels; ++k)
                grids[k] = new int[] {Math.max(1, (sizes[k][0] - PATCH) / STRIDE + 1),
                        Math.max(1, (sizes[k][1] - PATCH) / STRIDE + 1)};
            for (int s = 0; s < 2; ++s) {
                pyramid[s] = new int[levels];
                gradients[s] = new int[levels];
                for (int k = 0; k < levels; ++k) {
                    pyramid[s][k] = texture(sizes[k][0], sizes[k][1], false);
                    if (k >= finest) gradients[s][k] = texture(sizes[k][0], sizes[k][1], true);
                }
            }
            for (int d = 0; d < 2; ++d) {
                patches[d] = new int[levels];
                flows[d] = new int[levels];
                for (int k = finest; k < levels; ++k) {
                    patches[d][k] = texture(grids[k][0], grids[k][1], true);
                    flows[d][k] = texture(sizes[k][0], sizes[k][1], true);
                }
            }
            zeroField = texture(1, 1, true);
            used = finest;
            slotKey[0] = slotKey[1] = 0L;
            ready = true;
            Log.i(TAG, "DIS flow allocated history=" + width + "x" + height + " analysis=" + w + "x" + h +
                    " levels=" + levels + " finest=" + finest);
            return true;
        } catch (RuntimeException failure) {
            Log.w(TAG, "DIS flow unavailable", failure);
            failed = true;
            release();
            return false;
        }
    }

    boolean holds(int slot, long key) { return key != 0L && slotKey[slot] == key; }

    void swapSlots() {
        int[] t = pyramid[0]; pyramid[0] = pyramid[1]; pyramid[1] = t;
        int[] g = gradients[0]; gradients[0] = gradients[1]; gradients[1] = g;
        long k = slotKey[0]; slotKey[0] = slotKey[1]; slotKey[1] = k;
    }

    /** Per-real-frame work: the luma pyramid of one history image. */
    void encode(int slot, int historyTexture, long key) {
        saveState();
        try {
            begin(gray, sizes[0][0], sizes[0][1], pyramid[slot][0]);
            bind(gray, "uIn0", historyTexture, 0);
            GLES20.glUniform2f(location(gray, "uTexel"), 1f / historyWidth, 1f / historyHeight);
            GLES20.glUniform1i(location(gray, "uDivisor"), divisor);
            GLES20.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
            for (int k = 1; k < levels; ++k) {
                begin(down, sizes[k][0], sizes[k][1], pyramid[slot][k]);
                bind(down, "uIn0", pyramid[slot][k - 1], 0);
                GLES30.glUniform2i(location(down, "uIn"), sizes[k - 1][0], sizes[k - 1][1]);
                GLES20.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
            }
            for (int k = finest; k < levels; ++k) {
                begin(grad, sizes[k][0], sizes[k][1], gradients[slot][k]);
                bind(grad, "uIn0", pyramid[slot][k], 0);
                GLES30.glUniform2i(location(grad, "uSize"), sizes[k][0], sizes[k][1]);
                GLES20.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
            }
            slotKey[slot] = key;
            ++encodes;
        } finally {
            restoreState();
        }
    }

    /**
     * Per-pair work: flows A->C (slot 0 to 1) and C->A, down to pyramid level
     * {@code stopLevel} (0 = full analysis resolution; 1 when the engine
     * already saturates the GPU: about a third of the cost).
     */
    void estimate(int stopLevel) {
        saveState();
        try {
            used = Math.max(finest, Math.min(levels - 1, stopLevel));
            for (int d = 0; d < 2; ++d) {
                int ref = d == 0 ? 0 : 1, target = 1 - ref;
                int coarse = zeroField;
                for (int k = levels - 1; k >= used; --k) {
                    begin(patchSearch, grids[k][0], grids[k][1], patches[d][k]);
                    bind(patchSearch, "uRef", gradients[ref][k], 0);
                    bind(patchSearch, "uTarget", pyramid[target][k], 1);
                    bind(patchSearch, "uCoarse", coarse, 2);
                    GLES30.glUniform2i(location(patchSearch, "uSize"), sizes[k][0], sizes[k][1]);
                    GLES20.glUniform1f(location(patchSearch, "uHasCoarse"), coarse == zeroField ? 0f : 1f);
                    GLES20.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
                    begin(densify, sizes[k][0], sizes[k][1], flows[d][k]);
                    bind(densify, "uRef", pyramid[ref][k], 0);
                    bind(densify, "uTarget", pyramid[target][k], 1);
                    bind(densify, "uPatches", patches[d][k], 2);
                    GLES30.glUniform2i(location(densify, "uSize"), sizes[k][0], sizes[k][1]);
                    GLES30.glUniform2i(location(densify, "uGrid"), grids[k][0], grids[k][1]);
                    GLES20.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
                    coarse = flows[d][k];
                }
            }
            ++estimates;
        } finally {
            restoreState();
        }
    }

    /** Allocates the synthesis-22 field textures at the solver's analysis grid. */
    boolean ensureMotionTextures(int width, int height) {
        if (!ready) return false;
        if (motionRaw[0] != 0 && width == motionWidth && height == motionHeight) return true;
        for (int d = 0; d < 2; ++d) {
            motionRaw[d] = rgba8(width, height, true);
            motionValidated[d] = rgba8(width, height, false);
            motionFill[d] = rgba8(width, height, false);
        }
        motionWidth = width;
        motionHeight = height;
        return true;
    }

    /** Writes both flows into raw in source pixels (sourceWidth x sourceHeight). */
    void writeRaw(int[] raw, int sourceWidth, int sourceHeight, float limit) {
        saveState();
        try {
            for (int d = 0; d < 2; ++d) {
                // Raw [0] is current->previous: DIS direction 1 (reference C).
                int flow = flows[d == 0 ? 1 : 0][used];
                begin(toRaw, motionWidth, motionHeight, raw[d]);
                bind(toRaw, "uFlow", flow, 0);
                GLES20.glUniform2f(location(toRaw, "uScale"), (float) sourceWidth / sizes[used][0],
                        (float) sourceHeight / sizes[used][1]);
                GLES20.glUniform1f(location(toRaw, "uLimit"), limit);
                GLES30.glUniform2i(location(toRaw, "uOut"), motionWidth, motionHeight);
                GLES20.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
            }
        } finally {
            restoreState();
        }
    }

    private int rgba8(int width, int height, boolean nearest) {
        int[] id = new int[1];
        GLES20.glGenTextures(1, id, 0);
        GLES20.glBindTexture(GLES20.GL_TEXTURE_2D, id[0]);
        GLES20.glTexImage2D(GLES20.GL_TEXTURE_2D, 0, GLES20.GL_RGBA, width, height, 0,
                GLES20.GL_RGBA, GLES20.GL_UNSIGNED_BYTE, null);
        int filter = nearest ? GLES20.GL_NEAREST : GLES20.GL_LINEAR;
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_MIN_FILTER, filter);
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_MAG_FILTER, filter);
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_WRAP_S, GLES20.GL_CLAMP_TO_EDGE);
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_WRAP_T, GLES20.GL_CLAMP_TO_EDGE);
        owned.add(id[0]);
        return id[0];
    }

    /**
     * Per-phase work (synthesis 24): refines the motion through each output
     * pixel at time t by symmetric matching, A(x - t*v) = C(x + (1-t)*v),
     * starting from the better DIS proposal (the method of the REA-studied
     * design, implemented with DIS's patch alignment).
     */
    void estimatePhase(float t) {
        saveState();
        try {
            if (phaseLevel != used) {
                if (phasePatches != 0) {
                    GLES20.glDeleteTextures(2, new int[] {phasePatches, phaseFlow}, 0);
                    owned.remove(Integer.valueOf(phasePatches));
                    owned.remove(Integer.valueOf(phaseFlow));
                    verifiedTargets.remove(phasePatches);
                    verifiedTargets.remove(phaseFlow);
                }
                phasePatches = texture(grids[used][0], grids[used][1], true);
                phaseFlow = texture(sizes[used][0], sizes[used][1], true);
                phaseLevel = used;
            }
            begin(phaseSearch, grids[used][0], grids[used][1], phasePatches);
            bind(phaseSearch, "uGradA", gradients[0][used], 0);
            bind(phaseSearch, "uGradC", gradients[1][used], 1);
            bind(phaseSearch, "uFlowAC", flows[0][used], 2);
            bind(phaseSearch, "uFlowCA", flows[1][used], 3);
            GLES30.glUniform2i(location(phaseSearch, "uSize"), sizes[used][0], sizes[used][1]);
            GLES20.glUniform1f(location(phaseSearch, "uT"), t);
            GLES20.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
            begin(phaseDensify, sizes[used][0], sizes[used][1], phaseFlow);
            bind(phaseDensify, "uGrayA", pyramid[0][used], 0);
            bind(phaseDensify, "uGrayC", pyramid[1][used], 1);
            bind(phaseDensify, "uPatches", phasePatches, 2);
            GLES30.glUniform2i(location(phaseDensify, "uSize"), sizes[used][0], sizes[used][1]);
            GLES30.glUniform2i(location(phaseDensify, "uGrid"), grids[used][0], grids[used][1]);
            GLES20.glUniform1f(location(phaseDensify, "uT"), t);
            GLES20.glDrawArrays(GLES20.GL_TRIANGLES, 0, 3);
        } finally {
            restoreState();
        }
    }

    int generatePhaseProgram() { return generatePhase; }

    /**
     * structureMask 0: none. Otherwise synthesis 15's static-structure mask,
     * applied under warps of minMotionPx or more.
     */
    void bindGeneratePhase(int frameA, int frameC, float t, int structureMask, float minMotionPx) {
        GLES20.glUseProgram(generatePhase);
        GLES20.glUniform1f(location(generatePhase, "uStructure"), structureMask != 0 ? 1f : 0f);
        bind(generatePhase, "uStructureMask", structureMask != 0 ? structureMask : zeroField, 3);
        GLES20.glUniform1f(location(generatePhase, "uStructureMinMotionPx"), minMotionPx);
        GLES20.glUniform2f(location(generatePhase, "uHistorySize"), historyWidth, historyHeight);
        bind(generatePhase, "uFrameA", frameA, 0);
        bind(generatePhase, "uFrameC", frameC, 1);
        bind(generatePhase, "uPhaseFlow", phaseFlow, 2);
        GLES20.glUniform1f(location(generatePhase, "uT"), t);
        GLES20.glUniform2f(location(generatePhase, "uFlowSize"), sizes[used][0], sizes[used][1]);
    }

    int generateProgram() { return generate; }

    void bindGenerate(int frameA, int frameC, float t) {
        GLES20.glUseProgram(generate);
        bind(generate, "uFrameA", frameA, 0);
        bind(generate, "uFrameC", frameC, 1);
        bind(generate, "uFlowAC", flows[0][used], 2);
        bind(generate, "uFlowCA", flows[1][used], 3);
        GLES20.glUniform1f(location(generate, "uT"), t);
        GLES20.glUniform2f(location(generate, "uFlowSize"), sizes[used][0], sizes[used][1]);
    }

    // --- GL helpers -------------------------------------------------------------

    private void begin(int program, int width, int height, int target) {
        GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER, framebuffer);
        GLES20.glFramebufferTexture2D(GLES20.GL_FRAMEBUFFER, GLES20.GL_COLOR_ATTACHMENT0,
                GLES20.GL_TEXTURE_2D, target, 0);
        if (verifiedTargets.add(target) && GLES20.glCheckFramebufferStatus(GLES20.GL_FRAMEBUFFER) !=
                GLES20.GL_FRAMEBUFFER_COMPLETE)
            throw new IllegalStateException("DIS framebuffer incomplete");
        GLES20.glViewport(0, 0, width, height);
        GLES20.glUseProgram(program);
    }

    private void bind(int program, String name, int texture, int unit) {
        GLES20.glActiveTexture(GLES20.GL_TEXTURE0 + unit);
        GLES20.glBindTexture(GLES20.GL_TEXTURE_2D, texture);
        GLES20.glUniform1i(location(program, name), unit);
    }

    private int location(int program, String name) {
        Map<String, Integer> cache = uniforms.get(program);
        if (cache == null) uniforms.put(program, cache = new HashMap<>());
        Integer value = cache.get(name);
        if (value == null) cache.put(name, value = GLES20.glGetUniformLocation(program, name));
        return value;
    }

    private void saveState() {
        GLES20.glGetIntegerv(GLES20.GL_FRAMEBUFFER_BINDING, savedFramebuffer, 0);
        GLES20.glGetIntegerv(GLES20.GL_VIEWPORT, savedViewport, 0);
    }

    private void restoreState() {
        GLES20.glBindFramebuffer(GLES20.GL_FRAMEBUFFER, savedFramebuffer[0]);
        GLES20.glViewport(savedViewport[0], savedViewport[1], savedViewport[2], savedViewport[3]);
        GLES20.glActiveTexture(GLES20.GL_TEXTURE0);
    }

    private void compile() {
        String v = DenseInverseSearchShaders.VERTEX;
        gray = link(v, DenseInverseSearchShaders.GRAY);
        down = link(v, DenseInverseSearchShaders.DOWN);
        grad = link(v, DenseInverseSearchShaders.GRAD);
        patchSearch = link(v, DenseInverseSearchShaders.PATCH_SEARCH);
        densify = link(v, DenseInverseSearchShaders.DENSIFY);
        generate = link(DenseInverseSearchShaders.VERTEX_QUAD, DenseInverseSearchShaders.GENERATE);
        toRaw = link(v, DenseInverseSearchShaders.TO_RAW);
        phaseSearch = link(v, DenseInverseSearchShaders.PHASE_SEARCH);
        phaseDensify = link(v, DenseInverseSearchShaders.PHASE_DENSIFY);
        generatePhase = link(DenseInverseSearchShaders.VERTEX_QUAD, DenseInverseSearchShaders.GENERATE_PHASE);
        int[] ids = new int[1];
        GLES20.glGenFramebuffers(1, ids, 0);
        framebuffer = ids[0];
    }

    private static int link(String vertex, String fragment) {
        int vs = shader(GLES20.GL_VERTEX_SHADER, vertex), fs = shader(GLES20.GL_FRAGMENT_SHADER, fragment);
        int program = GLES20.glCreateProgram();
        GLES20.glAttachShader(program, vs);
        GLES20.glAttachShader(program, fs);
        GLES20.glLinkProgram(program);
        GLES20.glDeleteShader(vs);
        GLES20.glDeleteShader(fs);
        int[] ok = new int[1];
        GLES20.glGetProgramiv(program, GLES20.GL_LINK_STATUS, ok, 0);
        if (ok[0] == 0) {
            String log = GLES20.glGetProgramInfoLog(program);
            GLES20.glDeleteProgram(program);
            throw new IllegalStateException("DIS program link failed: " + log);
        }
        return program;
    }

    private static int shader(int type, String source) {
        int shader = GLES20.glCreateShader(type);
        GLES20.glShaderSource(shader, source);
        GLES20.glCompileShader(shader);
        int[] ok = new int[1];
        GLES20.glGetShaderiv(shader, GLES20.GL_COMPILE_STATUS, ok, 0);
        if (ok[0] == 0) {
            String log = GLES20.glGetShaderInfoLog(shader);
            GLES20.glDeleteShader(shader);
            throw new IllegalStateException("DIS shader compile failed: " + log);
        }
        return shader;
    }

    private int texture(int width, int height, boolean half) {
        int[] id = new int[1];
        GLES20.glGenTextures(1, id, 0);
        GLES20.glBindTexture(GLES20.GL_TEXTURE_2D, id[0]);
        if (half) {
            java.nio.ByteBuffer zeros = java.nio.ByteBuffer.allocateDirect(width * height * 8)
                    .order(java.nio.ByteOrder.nativeOrder());
            GLES30.glTexImage2D(GLES20.GL_TEXTURE_2D, 0, GLES30.GL_RGBA16F, width, height, 0,
                    GLES20.GL_RGBA, GLES30.GL_HALF_FLOAT, zeros);
        } else {
            GLES30.glTexImage2D(GLES20.GL_TEXTURE_2D, 0, GLES30.GL_R8, width, height, 0,
                    GLES30.GL_RED, GLES20.GL_UNSIGNED_BYTE, null);
        }
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_MIN_FILTER, GLES20.GL_LINEAR);
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_MAG_FILTER, GLES20.GL_LINEAR);
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_WRAP_S, GLES20.GL_CLAMP_TO_EDGE);
        GLES20.glTexParameteri(GLES20.GL_TEXTURE_2D, GLES20.GL_TEXTURE_WRAP_T, GLES20.GL_CLAMP_TO_EDGE);
        owned.add(id[0]);
        return id[0];
    }

    private void releaseTextures() {
        if (!owned.isEmpty()) {
            int[] ids = new int[owned.size()];
            for (int i = 0; i < ids.length; ++i) ids[i] = owned.get(i);
            GLES20.glDeleteTextures(ids.length, ids, 0);
            owned.clear();
        }
        verifiedTargets.clear();
        java.util.Arrays.fill(motionRaw, 0);
        java.util.Arrays.fill(motionValidated, 0);
        java.util.Arrays.fill(motionFill, 0);
        motionWidth = motionHeight = 0;
        phasePatches = phaseFlow = 0;
        phaseLevel = -1;
        ready = false;
    }

    void release() {
        releaseTextures();
        for (int program : new int[] {gray, down, grad, patchSearch, densify, generate, toRaw,
                phaseSearch, phaseDensify, generatePhase})
            if (program != 0) GLES20.glDeleteProgram(program);
        gray = down = grad = patchSearch = densify = generate = toRaw = 0;
        phaseSearch = phaseDensify = generatePhase = 0;
        uniforms.clear();
        if (framebuffer != 0) GLES20.glDeleteFramebuffers(1, new int[] {framebuffer}, 0);
        framebuffer = 0;
    }
}
